  for (const a of [0, Math.PI / 2]) bx2(b, kit.shell, r * 1.7 * Math.abs(Math.cos(a)) + r * 0.05, r * 0.05, r * 1.7 * Math.abs(Math.sin(a)) + r * 0.05, x, y + r * 0.82 * dir, z);
